pub fn set_slice(&mut self, rhs: &Self, s: usize) {
    let (m, n) = self.dim();
    debug_assert!(s < m);
    debug_assert!(s + rhs.dim().0 <= m);

    let rhs_data = rhs.convert_to_vec();
    let self_data = self.convert_to_vec();

    for (i, value) in rhs_data.iter().enumerate() {
        self_data[s + i] = *value;
    }

    *self = Vector::new_column(self_data);
}
